/* Weeks 6-9: Credit cards; Loans and amortization; Credit scores and the cost of borrowing; Project: a first-year budget */
const loanPay = (P, apr, n) => { const r = apr/1200; return P*r/(1-Math.pow(1+r,-n)); };
const payoffN = (B, apr, P) => { const r = apr/1200; return -Math.log(1-r*B/P)/Math.log(1+r); };
const CARD_APRS = [15.99,18.99,19.99,21.49,22.99,24.99,27.99];
const LOAN_APRS = [4.5,5,5.5,6,6.5,7,7.5,8,9];
const cap1 = s => s[0].toUpperCase()+s.slice(1);

Object.assign(G, {
/* ---- Week 6: Credit cards ---- */
cc_util(rng){const lim=R(10,60)*100,bal=Math.round(lim*R(8,90)/100/10)*10;
  return{q:`His credit card has a limit of ${$m(lim)} and a balance of ${$m(bal)}. What is his credit utilization? (One decimal.)`,ans:bal/lim*100,unit:"%",abs:.06,hint:`Utilization is how much of the limit is being used: balance ÷ limit.`,steps:[`${$m(bal)} ÷ ${$m(lim)} = ${nf(bal/lim,4)}`,`= ${nf(bal/lim*100,1)}%`]}},
cc_avail(rng){const lim=R(10,50)*100,bal=R(2,Math.floor(lim/100)-4)*50+R(0,99)/100,buy=R(20,300)+pick(rng,[0,.49,.99]);const av=lim-bal-buy;
  return{q:`A card has a ${$m(lim)} limit and a balance of ${$m(r2(bal))}. He buys a ${$m(buy)} pair of shoes with it. How much available credit is left?`,ans:av,unit:"$",abs:.01,tol:0,hint:`Available credit is the limit minus everything already owed.`,steps:[`New balance: ${$m(r2(bal))} + ${$m(buy)} = ${$m(r2(bal+buy))}`,`Available: ${$m(lim)} − ${$m(r2(bal+buy))} = ${$m(r2(av))}`]}},
cc_mpr(rng){const a=pick(rng,CARD_APRS);
  return{q:`A credit card has an APR of ${a}%. What is its monthly periodic rate? (Three decimals.)`,ans:a/12,unit:"%",abs:.0015,hint:`Card interest is charged monthly. Spread the yearly rate over 12 months.`,steps:[`${a}% ÷ 12 = ${nf(a/12,3)}%`]}},
cc_month_int(rng){const b=R(4,60)*50+R(0,99)/100,a=pick(rng,CARD_APRS),i=b*a/1200;
  return{q:`He carries a balance of ${$m(r2(b))} on a card with a ${a}% APR. Using the monthly rate, how much interest is charged this month?`,ans:i,unit:"$",tol:.004,hint:`Find the monthly rate (APR ÷ 12), then multiply by the balance.`,steps:[`Monthly rate: ${a}% ÷ 12 = ${nf(a/12,4)}% = ${nf(a/1200,6)}`,`Interest = ${$m(r2(b))} × ${nf(a/1200,6)} = ${$m(r2(i))}`]}},
cc_terms_mc(rng){const k=R(0,5);const Q=[
  ["The time between the end of a billing cycle and the due date, when new purchases are interest‑free if the full balance is paid, is the:","Grace period",["Grace period","Credit limit","APR","Billing cycle"]],
  ["The most a card company lets you borrow on a card is the:","Credit limit",["Credit limit","Minimum payment","Statement balance","Grace period"]],
  ["He pays the full statement balance by the due date every month. How much interest does he pay on purchases?","$0",["$0","The APR on the full balance","The minimum payment","Half the APR"]],
  ["The smallest amount you can pay by the due date without a late fee is the:","Minimum payment",["Minimum payment","Statement balance","Credit limit","Annual fee"]],
  ["Which of these is a credit card, not a debit card?","It borrows money you pay back later",["It borrows money you pay back later","It takes money straight from your checking account","It can never charge interest","It needs no bill"]],
  ["What happens if you pay only part of the statement balance?","Interest is charged on the unpaid balance",["Interest is charged on the unpaid balance","Nothing, as long as it's before the due date","The card is cancelled","The credit limit goes up"]]][k];
  return{q:Q[0],choices:shuffle(rng,Q[2]),correctText:Q[1],hint:`This was covered in the lesson on how credit cards work.`,steps:[`${Q[1]}.`]}},
cc_adb(rng){const b1=R(4,20)*50,d1=R(6,24),add=R(4,30)*10,b2=b1+add,adb=(b1*d1+b2*(30-d1))/30;
  return{q:`In a 30‑day billing cycle, his balance was ${$m(b1)} for the first ${d1} days. Then he made a ${$m(add)} purchase, and the balance stayed at ${$m(b2)} for the other ${30-d1} days. What is the average daily balance?`,ans:adb,unit:"$",tol:.002,hint:`Multiply each balance by the number of days it lasted, add, then divide by 30.`,steps:[`${$m(b1)} × ${d1} = ${$m(b1*d1)}`,`${$m(b2)} × ${30-d1} = ${$m(b2*(30-d1))}`,`Sum = ${$m(b1*d1+b2*(30-d1))}`,`÷ 30 = ${$m(r2(adb))}`]}},
cc_adb_int(rng){const adb=R(6,50)*25,a=pick(rng,CARD_APRS),d=pick(rng,[28,30,31]),i=adb*a/100/365*d;
  return{q:`The average daily balance for a ${d}‑day billing cycle is ${$m(adb)}. The APR is ${a}%. Using a daily rate of APR ÷ 365, how much interest is charged for the cycle?`,ans:i,unit:"$",tol:.004,hint:`Daily rate = APR ÷ 365. Interest = average daily balance × daily rate × days in the cycle.`,steps:[`Daily rate: ${nf(a/100,4)} ÷ 365 = ${nf(a/100/365,7)}`,`Interest = ${$m(adb)} × ${nf(a/100/365,7)} × ${d} = ${$m(r2(i))}`]}},
cc_year(rng){const b=R(10,60)*100,a=pick(rng,CARD_APRS);
  return{q:`He keeps a balance of about ${$m(b)} on a ${a}% card all year without paying it down. About how much interest does that cost him in a year? (Use APR × balance.)`,ans:b*a/100,unit:"$",tol:.004,hint:`For a rough yearly cost, multiply the balance by the APR as a decimal.`,steps:[`${$m(b)} × ${nf(a/100,4)} = ${$m(r2(b*a/100))}`]}},
cc_minpay(rng){const p=pick(rng,[1,2,3]),fl=pick(rng,[25,35]),b=rng()<.3?R(5,Math.floor(fl*100/p/10))*10:R(Math.ceil(fl*100/p/100)+1,60)*100;const m=Math.max(b*p/100,fl);
  return{q:`His card's minimum payment is the greater of ${p}% of the balance or ${$m(fl)}. His balance is ${$m(b)}. What is the minimum payment?`,ans:Math.min(m,b),unit:"$",hint:`Work out ${p}% of the balance, then compare it with ${$m(fl)}. The bigger one wins.`,steps:[`${p}% of ${$m(b)} = ${$m(r2(b*p/100))}`,`Compare with ${$m(fl)}: the greater is ${$m(r2(Math.min(m,b)))}`]}},
cc_split(rng){const b=R(10,50)*100,a=pick(rng,CARD_APRS),i=b*a/1200,pay=Math.ceil((i+R(10,120))/10)*10,pr=pay-i;
  return{q:`He owes ${$m(b)} on a ${a}% card and makes a ${$m(pay)} payment. Interest for the month is figured first, using APR ÷ 12. How much of his payment actually lowers what he owes?`,ans:pr,unit:"$",tol:.004,hint:`Part of every payment covers the month's interest. Only the rest pays down the balance.`,steps:[`Interest: ${$m(b)} × ${nf(a/1200,6)} = ${$m(r2(i))}`,`Toward the balance: ${$m(pay)} − ${$m(r2(i))} = ${$m(r2(pr))}`]}},
cc_payoff(rng){const b=R(10,60)*100,a=pick(rng,CARD_APRS);const pay=Math.ceil(b*(a/1200+R(15,40)/1000)/5)*5;const r=a/1200,n=payoffN(b,a,pay),N=Math.ceil(n);
  return{q:`He owes ${$m(b)} on a ${a}% card, stops using it, and pays ${$m(pay)} a month. How many months until it's paid off? Use n = −log(1 − r × B ÷ P) ÷ log(1 + r), with r = APR ÷ 12 as a decimal. (Round up to a whole month.)`,ans:N,unit:"months",abs:0,tol:0,hint:`r = ${a} ÷ 1200. Find r × B ÷ P first, subtract it from 1, then take the logs. Any log key works, as long as you use the same one top and bottom.`,steps:[`r = ${a} ÷ 1200 = ${nf(r,6)}`,`r × B ÷ P = ${nf(r,6)} × ${b} ÷ ${pay} = ${nf(r*b/pay,5)}`,`n = −log(${nf(1-r*b/pay,5)}) ÷ log(${nf(1+r,6)}) = ${nf(n,2)}`,`Round up: ${N} months`]}},
cc_fee(rng){const k=R(0,1);if(k===0){const a=R(10,60)*10,f=pick(rng,[3,4,5]),mn=10,fee=Math.max(a*f/100,mn);
  return{q:`A cash advance has a fee of ${f}% of the amount or ${$m(mn)}, whichever is greater. He takes a ${$m(a)} cash advance. What is the fee?`,ans:fee,unit:"$",hint:`Find ${f}% of the amount and compare with ${$m(mn)}.`,steps:[`${f}% of ${$m(a)} = ${$m(r2(a*f/100))}`,`The greater amount: ${$m(r2(fee))}`]}}
  const b=R(10,80)*100,f=pick(rng,[3,4,5]);return{q:`He moves a ${$m(b)} balance to a new card with a 0% intro APR. The balance transfer fee is ${f}%. How much is the fee?`,ans:b*f/100,unit:"$",hint:`A percent of the amount moved.`,steps:[`${$m(b)} × ${f/100} = ${$m(b*f/100)}`]}},
cc_total_int(rng){const b=R(10,50)*100,a=pick(rng,CARD_APRS),n=pick(rng,[12,18,24,36]),p=r2(loanPay(b,a,n)),t=p*n-b;
  return{q:`He pays off a ${$m(b)} card balance at ${a}% with ${n} equal monthly payments of ${$m(p)}. How much interest does he pay in total?`,ans:t,unit:"$",tol:.004,hint:`Total paid minus what he borrowed is the interest.`,steps:[`Total paid: ${$m(p)} × ${n} = ${$m(r2(p*n))}`,`Interest: ${$m(r2(p*n))} − ${$m(b)} = ${$m(r2(t))}`]}},

/* ---- Week 7: Loans and amortization ---- */
ln_pmt(rng){const P=R(8,40)*500,a=pick(rng,LOAN_APRS),y=pick(rng,[2,3,4,5]),n=y*12,r=a/1200,p=loanPay(P,a,n);
  return{q:`A ${$m(P)} loan has an APR of ${a}% and is paid monthly for ${y} years. What is the monthly payment?`,ans:p,unit:"$",tol:.003,hint:`Use PMT = P × r ÷ (1 − (1 + r)<sup>−n</sup>), with r = APR ÷ 12 as a decimal and n = number of months.`,steps:[`r = ${a} ÷ 1200 = ${nf(r,6)}, n = ${y} × 12 = ${n}`,`(1 + r)<sup>−${n}</sup> = ${nf(Math.pow(1+r,-n),6)}`,`1 − that = ${nf(1-Math.pow(1+r,-n),6)}`,`PMT = ${$m(P)} × ${nf(r,6)} ÷ ${nf(1-Math.pow(1+r,-n),6)} = ${$m(r2(p))}`]}},
ln_total(rng){const P=R(8,40)*500,a=pick(rng,LOAN_APRS),y=pick(rng,[3,4,5,6]),n=y*12,p=r2(loanPay(P,a,n)),t=p*n-P;
  return{q:`A ${$m(P)} car loan at ${a}% for ${y} years has a monthly payment of ${$m(p)}. How much interest is paid over the whole loan?`,ans:t,unit:"$",tol:.003,hint:`Find everything he pays over the loan, then subtract the amount borrowed.`,steps:[`Payments: ${y} × 12 = ${n}`,`Total paid: ${$m(p)} × ${n} = ${$m(r2(p*n))}`,`Interest: ${$m(r2(p*n))} − ${$m(P)} = ${$m(r2(t))}`]}},
ln_terms_mc(rng){const k=R(0,5);const Q=[
  ["The amount borrowed on a loan, not counting interest, is the:","Principal",["Principal","Term","Collateral","APR"]],
  ["How long you have to pay back a loan is its:","Term",["Term","Principal","Collateral","Grace period"]],
  ["Something the lender can take if you stop paying, like the car on a car loan, is called:","Collateral",["Collateral","A cosigner","Principal","Equity"]],
  ["Paying a loan off with equal payments that cover interest and part of the principal is called:","Amortization",["Amortization","Compounding","Inflation","Utilization"]],
  ["Someone who promises to repay a loan if the borrower doesn't is a:","Cosigner",["Cosigner","Lender","Bureau","Broker"]],
  ["A loan with no collateral, like most credit cards, is called:","Unsecured",["Unsecured","Secured","Amortized","Fixed"]]][k];
  return{q:Q[0],choices:shuffle(rng,Q[2]),correctText:Q[1],hint:`Think back to the loan vocabulary from today's lesson.`,steps:[`${Q[1]}.`]}},
am_int1(rng){const P=R(10,60)*500,a=pick(rng,LOAN_APRS),i=P*a/1200;
  return{q:`He borrows ${$m(P)} at ${a}% APR, paid monthly. How much of the first payment is interest?`,ans:i,unit:"$",tol:.003,hint:`The first month's interest is the whole balance times the monthly rate.`,steps:[`Monthly rate: ${a} ÷ 1200 = ${nf(a/1200,6)}`,`Interest = ${$m(P)} × ${nf(a/1200,6)} = ${$m(r2(i))}`]}},
am_prin1(rng){const P=R(10,60)*500,a=pick(rng,LOAN_APRS),y=pick(rng,[3,4,5]),p=r2(loanPay(P,a,y*12)),i=r2(P*a/1200);
  return{q:`A ${$m(P)} loan at ${a}% has a monthly payment of ${$m(p)}. How much of the first payment goes to principal?`,ans:p-i,unit:"$",tol:.003,hint:`Figure the first month's interest. Whatever is left of the payment goes to principal.`,steps:[`Interest: ${$m(P)} × ${nf(a/1200,6)} = ${$m(i)}`,`Principal: ${$m(p)} − ${$m(i)} = ${$m(r2(p-i))}`]}},
am_bal2(rng){const P=R(10,60)*500,a=pick(rng,LOAN_APRS),y=pick(rng,[3,4,5]),p=r2(loanPay(P,a,y*12)),r=a/1200,i1=r2(P*r),b1=r2(P-(p-i1)),i2=r2(b1*r),b2=r2(b1-(p-i2));
  return{q:`A ${$m(P)} loan at ${a}% has a monthly payment of ${$m(p)}. What is the balance after the first two payments? (Round interest to the cent each month.)`,ans:b2,unit:"$",tol:.001,hint:`Do one row of the schedule at a time: interest, principal, new balance. Then repeat.`,steps:[`Month 1 interest: ${$m(P)} × ${nf(r,6)} = ${$m(i1)}`,`Month 1 balance: ${$m(P)} − (${$m(p)} − ${$m(i1)}) = ${$m(b1)}`,`Month 2 interest: ${$m(b1)} × ${nf(r,6)} = ${$m(i2)}`,`Month 2 balance: ${$m(b1)} − (${$m(p)} − ${$m(i2)}) = ${$m(b2)}`]}},
am_trend_mc(rng){const k=R(0,2);const Q=[
  ["As a fixed‑rate loan is paid off, what happens to the interest part of each payment?","It shrinks",["It shrinks","It grows","It stays the same","It disappears after month 1"]],
  ["As a fixed‑rate loan is paid off, what happens to the principal part of each payment?","It grows",["It grows","It shrinks","It stays the same","It is always zero"]],
  ["Why is so much of an early payment interest?","The balance is largest at the start",["The balance is largest at the start","Lenders charge a higher rate at first","The payment is bigger at first","Principal can't be paid early"]]][k];
  return{q:Q[0],choices:shuffle(rng,Q[2]),correctText:Q[1],hint:`Interest each month is figured on the balance that's still owed.`,steps:[`${Q[1]}.`]}},
ln_compare(rng){const P=R(12,40)*500,a=pick(rng,LOAN_APRS),y1=3,y2=pick(rng,[5,6]),p1=r2(loanPay(P,a,36)),p2=r2(loanPay(P,a,y2*12)),t1=p1*36-P,t2=p2*y2*12-P;
  return{q:`A ${$m(P)} loan at ${a}% can be repaid over 3 years (${$m(p1)} a month) or ${y2} years (${$m(p2)} a month). How much more total interest does the ${y2}‑year loan cost?`,ans:t2-t1,unit:"$",tol:.004,hint:`Find the total interest for each loan, then subtract.`,steps:[`3 years: ${$m(p1)} × 36 − ${$m(P)} = ${$m(r2(t1))}`,`${y2} years: ${$m(p2)} × ${y2*12} − ${$m(P)} = ${$m(r2(t2))}`,`Difference: ${$m(r2(t2-t1))}`]}},
ln_down(rng){const price=R(16,45)*500,d=pick(rng,[10,15,20]),a=pick(rng,LOAN_APRS),y=pick(rng,[3,4,5]),P=price*(1-d/100),p=loanPay(P,a,y*12);
  return{q:`A used car costs ${$m(price)}. He puts ${d}% down and finances the rest at ${a}% for ${y} years. What is his monthly payment?`,ans:p,unit:"$",tol:.003,hint:`The loan is only the part he doesn't pay up front. Then use the payment formula.`,steps:[`Down payment: ${$m(price)} × ${d/100} = ${$m(price*d/100)}`,`Loan: ${$m(price)} − ${$m(price*d/100)} = ${$m(P)}`,`r = ${nf(a/1200,6)}, n = ${y*12}`,`PMT = ${$m(P)} × ${nf(a/1200,6)} ÷ (1 − ${nf(Math.pow(1+a/1200,-y*12),6)}) = ${$m(r2(p))}`]}},
ln_afford(rng){const p=R(15,60)*10,a=pick(rng,LOAN_APRS),y=pick(rng,[3,4,5]),n=y*12,r=a/1200,P=p*(1-Math.pow(1+r,-n))/r;
  return{q:`He can afford a car payment of ${$m(p)} a month. Loans are ${a}% for ${y} years. What is the most he can borrow? Use P = PMT × (1 − (1 + r)<sup>−n</sup>) ÷ r.`,ans:P,unit:"$",tol:.003,hint:`This is the payment formula worked backward. r = APR ÷ 12 as a decimal, n = months.`,steps:[`r = ${nf(r,6)}, n = ${n}`,`1 − (1 + r)<sup>−${n}</sup> = ${nf(1-Math.pow(1+r,-n),6)}`,`P = ${$m(p)} × ${nf(1-Math.pow(1+r,-n),6)} ÷ ${nf(r,6)} = ${$m(r2(P))}`]}},
ln_extra(rng){const P=R(10,40)*500,a=pick(rng,LOAN_APRS),y=5,p=r2(loanPay(P,a,60)),x=pick(rng,[25,50,75,100]),n=payoffN(P,a,p+x),N=Math.ceil(n);
  return{q:`A ${$m(P)} loan at ${a}% has a 60‑month payment of ${$m(p)}. If he pays ${$m(x)} extra every month, how many months will it take? Use n = −log(1 − r × P ÷ PMT) ÷ log(1 + r). (Round up.)`,ans:N,unit:"months",abs:0,tol:0,hint:`The new payment is ${$m(p)} + ${$m(x)}. Use that as PMT in the formula.`,steps:[`New payment: ${$m(r2(p+x))}`,`r × P ÷ PMT = ${nf(a/1200,6)} × ${P} ÷ ${r2(p+x)} = ${nf(a/1200*P/(p+x),5)}`,`n = −log(${nf(1-a/1200*P/(p+x),5)}) ÷ log(${nf(1+a/1200,6)}) = ${nf(n,2)}`,`Round up: ${N} months, ${60-N} months sooner`]}},

/* ---- Week 8: Credit scores and the cost of borrowing ---- */
fico_weight(rng){const f=pick(rng,[["payment history","35%"],["amounts owed","30%"],["length of credit history","15%"],["new credit","10%"],["credit mix","10%"]]);
  return{q:`About what share of a FICO score is based on ${f[0]}?`,choices:shuffle(rng,["35%","30%","15%","10%"]),correctText:f[1],hint:`The biggest factor is paying on time, then how much you owe.`,steps:[`${cap1(f[0])}: about ${f[1]}.`]}},
fico_factor(rng){const k=R(0,6);const Q=[["paying a phone bill 60 days late","Payment history"],["running a card up close to its limit","Amounts owed"],["having had credit accounts for 12 years","Length of credit history"],["applying for four new cards in one month","New credit"],["having a car loan and a credit card, not just cards","Credit mix"],["paying every bill on time for three years","Payment history"],["paying a card balance down from 80% to 10% of the limit","Amounts owed"]][k];
  return{q:`Which part of a credit score does this affect most: ${Q[0]}?`,choices:shuffle(rng,["Payment history","Amounts owed","Length of credit history","New credit","Credit mix"]),correctText:Q[1],hint:`Match the action to one of the five FICO factors.`,steps:[`${Q[1]}.`]}},
cs_util_total(rng){const n=pick(rng,[2,3]),cards=[...Array(n)].map(()=>{const l=R(5,40)*100;return[l,Math.round(l*R(0,70)/100/10)*10]}),L0=cards.reduce((a,c)=>a+c[0],0),B0=cards.reduce((a,c)=>a+c[1],0);
  return{q:`He has ${n} cards: ${cards.map((c,i)=>`card ${i+1} has a ${$m(c[0])} limit and a ${$m(c[1])} balance`).join("; ")}. What is his overall credit utilization? (One decimal.)`,ans:B0/L0*100,unit:"%",abs:.06,hint:`Add all the balances and all the limits, then divide.`,steps:[`Balances: ${$m(B0)}`,`Limits: ${$m(L0)}`,`${$m(B0)} ÷ ${$m(L0)} = ${nf(B0/L0*100,1)}%`]}},
cs_facts_mc(rng){const k=R(0,5);const Q=[
  ["FICO scores range from:","300 to 850",["300 to 850","0 to 100","100 to 1,000","500 to 900"]],
  ["Checking your own credit score:","Does not hurt it",["Does not hurt it","Lowers it a lot","Raises it","Closes your accounts"]],
  ["When you apply for a new loan, the lender's check of your credit is a:","Hard inquiry",["Hard inquiry","Soft inquiry","Credit freeze","Default"]],
  ["The three national credit bureaus are Equifax, Experian and:","TransUnion",["TransUnion","Visa","the IRS","the Federal Reserve"]],
  ["Where can you get your credit reports for free?","AnnualCreditReport.com",["AnnualCreditReport.com","Any bank's lobby","The post office","Only from a paid service"]],
  ["You find a mistake on your credit report. What should you do?","Dispute it with the credit bureau",["Dispute it with the credit bureau","Nothing; it can't be changed","Open new cards to hide it","Close all your accounts"]]][k];
  return{q:Q[0],choices:shuffle(rng,Q[2]),correctText:Q[1],hint:`This was covered in today's lesson on credit reports.`,steps:[`${Q[1]}.`]}},
rate_diff_pmt(rng){const P=R(16,60)*500,y=pick(rng,[4,5]),a1=pick(rng,[5,5.5,6]),a2=a1+pick(rng,[4,6,8,10]),p1=loanPay(P,a1,y*12),p2=loanPay(P,a2,y*12);
  return{q:`Two borrowers each take a ${$m(P)} car loan for ${y} years. One has excellent credit and gets ${a1}%. The other has fair credit and gets ${a2}%. How much more is the second borrower's monthly payment?`,ans:p2-p1,unit:"$",tol:.006,hint:`Find each monthly payment with the payment formula, then subtract.`,steps:[`At ${a1}%: ${$m(r2(p1))} a month`,`At ${a2}%: ${$m(r2(p2))} a month`,`Difference: ${$m(r2(p2-p1))}`]}},
rate_diff_total(rng){const P=R(16,60)*500,y=pick(rng,[4,5]),a1=pick(rng,[5,5.5,6]),a2=a1+pick(rng,[4,6,8]),p1=r2(loanPay(P,a1,y*12)),p2=r2(loanPay(P,a2,y*12)),n=y*12;
  return{q:`On a ${$m(P)}, ${y}‑year loan, the payment is ${$m(p1)} at ${a1}% and ${$m(p2)} at ${a2}%. Over the whole loan, how much more interest does the higher rate cost?`,ans:(p2-p1)*n,unit:"$",tol:.003,hint:`Both borrow the same amount, so the extra interest is just the extra payments added up.`,steps:[`Extra each month: ${$m(p2)} − ${$m(p1)} = ${$m(r2(p2-p1))}`,`× ${n} months = ${$m(r2((p2-p1)*n))}`]}},
payday_apr(rng){const f=pick(rng,[10,12,15,18,20,25]);
  return{q:`A payday lender charges ${$m(f)} for every $100 borrowed for two weeks. There are 26 two‑week periods in a year. What is the APR?`,ans:f*26,unit:"%",abs:.1,hint:`First find the rate for two weeks, then make it yearly.`,steps:[`Two‑week rate: ${f} ÷ 100 = ${f}%`,`APR: ${f}% × 26 = ${f*26}%`]}},
payday_roll(rng){const b=pick(rng,[200,300,400,500]),f=pick(rng,[15,20]),k=R(2,6),fees=b/100*f*(k+1);
  return{q:`He borrows ${$m(b)} from a payday lender at ${$m(f)} per $100 for two weeks. He can't repay, so he rolls the loan over ${k} times, paying the fee each time, and then pays it off. How much has he paid in fees in total?`,ans:fees,unit:"$",hint:`He pays the fee for the first two weeks, plus once for every rollover.`,steps:[`Fee each time: ${b} ÷ 100 × ${$m(f)} = ${$m(b/100*f)}`,`Times paid: 1 + ${k} = ${k+1}`,`Total fees: ${$m(fees)}`]}},
rto_total(rng){const price=R(30,120)*10,wk=pick(rng,[52,78,104]),w=Math.ceil(price*R(14,24)/10/wk),tot=w*wk;
  return{q:`A TV costs ${$m(price)} in the store. A rent‑to‑own store offers it for ${$m(w)} a week for ${wk} weeks. How much more than the store price does rent‑to‑own cost?`,ans:tot-price,unit:"$",abs:.01,tol:0,hint:`Find the total of all the weekly payments first.`,steps:[`Total: ${$m(w)} × ${wk} = ${$m(tot)}`,`Extra: ${$m(tot)} − ${$m(price)} = ${$m(tot-price)}`]}},
fee_pct(rng){const P=R(4,30)*500,f=pick(rng,[1,2,3,4,5]);
  return{q:`A personal loan of ${$m(P)} has an origination fee of ${f}%, taken out of the loan before he gets the money. How much cash does he actually receive?`,ans:P*(1-f/100),unit:"$",hint:`The fee is a percent of the loan, subtracted up front.`,steps:[`Fee: ${$m(P)} × ${f/100} = ${$m(P*f/100)}`,`Received: ${$m(P)} − ${$m(P*f/100)} = ${$m(P*(1-f/100))}`]}},
trap_mc(rng){const k=R(0,4);const Q=[
  ["Which usually has the highest APR?","A payday loan",["A payday loan","A credit card","A car loan from a bank","A mortgage"]],
  ["Paying the fee to extend a payday loan for another two weeks is called:","Rolling it over",["Rolling it over","Refinancing it","Amortizing it","Consolidating it"]],
  ["Buy now, pay later plans split a purchase into a few payments. What is the biggest risk?","Late fees and spending more than you planned",["Late fees and spending more than you planned","They always charge 30% interest","They lower the store price","They can't be used online"]],
  ["Rent‑to‑own is usually expensive because:","The weekly payments add up to far more than the store price",["The weekly payments add up to far more than the store price","The item is new","It has no fees","The store pays you interest"]],
  ["What is the best way to avoid needing a payday loan?","Build an emergency fund",["Build an emergency fund","Get more credit cards","Borrow from a rent‑to‑own store","Skip the budget"]]][k];
  return{q:Q[0],choices:shuffle(rng,Q[2]),correctText:Q[1],hint:`Think about which choice costs the most over time.`,steps:[`${Q[1]}.`]}},

/* ---- Week 9: Project ---- */
pj_net_month(rng){const s=R(36,70)*1000,k=pick(rng,[4,5,6]),f=pick(rng,[9,10,11,12]),st=4.25,g=s/12,c=g*k/100,tx=g-c,n=g-c-tx*f/100-tx*st/100-g*.0765;
  return{q:`Your first job pays a salary of ${$m(s)}. You put ${k}% into a pre‑tax 401(k). Federal withholding is ${f}% and Michigan's state tax is ${st}%, both figured after the 401(k). FICA is 7.65% of full gross pay. What is your monthly take‑home pay?`,ans:n,unit:"$",tol:.003,hint:`Start with monthly gross pay (salary ÷ 12). Then take out the 401(k), the income taxes on what's left, and FICA on the full gross.`,steps:[`Monthly gross: ${$m(s)} ÷ 12 = ${$m(r2(g))}`,`401(k): ${$m(r2(c))}, taxable: ${$m(r2(tx))}`,`Federal: ${$m(r2(tx*f/100))}, state: ${$m(r2(tx*st/100))}`,`FICA: ${$m(r2(g*.0765))}`,`Take‑home: ${$m(r2(n))}`]}},
pj_max_rent(rng){const s=R(36,80)*1000;
  return{q:`A common guideline says rent should be at most 30% of monthly gross pay. Your salary is ${$m(s)}. What is the most you should pay in rent each month?`,ans:s/12*.3,unit:"$",hint:`Turn the yearly salary into monthly pay first.`,steps:[`Monthly gross: ${$m(s)} ÷ 12 = ${$m(r2(s/12))}`,`× 0.30 = ${$m(r2(s/12*.3))}`]}},
pj_left(rng){const net=R(28,46)*100,rent=R(9,14)*100,car=R(22,40)*10,ins=R(9,18)*10,food=R(35,55)*10,ph=R(4,8)*10,ut=R(8,15)*10,m=net*.1,tot=rent+car+ins+food+ph+ut+m;
  return{q:`Your take‑home pay is ${$m(net)} a month. You pay yourself first by moving 10% of it into savings. Your bills are rent ${$m(rent)}, car payment ${$m(car)}, car insurance ${$m(ins)}, food ${$m(food)}, phone ${$m(ph)} and utilities ${$m(ut)}. How much is left for wants and extra savings? (Negative if short.)`,ans:net-tot,unit:"$",abs:.01,tol:0,hint:`Savings is 10% of take‑home. Add it to the bills, then subtract from take‑home pay.`,steps:[`Savings: ${$m(net)} × 0.10 = ${$m(m)}`,`Bills: ${$m(rent+car+ins+food+ph+ut)}`,`Total out: ${$m(tot)}`,`Left: ${$m(net)} − ${$m(tot)} = ${$m(r2(net-tot))}`]}},
pj_save_year(rng){const d=R(10,60)*10,a=pick(rng,[3,3.5,4,4.5,5]),r=a/1200,fv=d*(Math.pow(1+r,12)-1)/r;
  return{q:`You deposit ${$m(d)} at the end of every month into a savings account paying ${a}% a year, compounded monthly. How much is in the account after 12 months?`,ans:fv,unit:"$",tol:.002,hint:`This is the regular‑deposit formula, using a monthly rate (APR ÷ 12) and 12 deposits.`,steps:[`r = ${a} ÷ 1200 = ${nf(r,6)}`,`(1 + r)<sup>12</sup> = ${nf(Math.pow(1+r,12),6)}`,`FV = ${$m(d)} × (${nf(Math.pow(1+r,12),6)} − 1) ÷ ${nf(r,6)} = ${$m(r2(fv))}`]}},
pj_raise(rng){const s=R(40,75)*1000,ra=pick(rng,[3,4,5]),sh=pick(rng,[50,100]),add=s*ra/100*sh/100/12;
  return{q:`Your ${$m(s)} salary gets a ${ra}% raise. To beat lifestyle creep, you send ${sh===100?"all":"half"} of the raise straight to savings. How much more do you save each month, before taxes?`,ans:add,unit:"$",hint:`Find the raise per year, take your share of it, then divide by 12.`,steps:[`Raise: ${$m(s)} × ${ra/100} = ${$m(s*ra/100)} a year`,`Saved: ${sh}% of that = ${$m(s*ra/100*sh/100)}`,`÷ 12 = ${$m(r2(add))} a month`]}},
pj_check_mc(rng){const k=R(0,4);const Q=[
  ["Your rent would be 38% of your gross pay. What does the guideline say?","It's above the 30% guideline; look for cheaper housing or a roommate",["It's above the 30% guideline; look for cheaper housing or a roommate","It's fine; rent has no guideline","It's too low","Put the rent on a credit card"]],
  ["Your budget has a $120 deficit. Which is a real fix?","Cut variable spending or raise income until it balances",["Cut variable spending or raise income until it balances","Pay the minimum on a credit card each month","Take a payday loan each month","Ignore it; it's small"]],
  ["You have $0 saved and a $900 car repair comes up. What should have been in the plan?","An emergency fund",["An emergency fund","A higher credit limit","A rent‑to‑own plan","A bigger car payment"]],
  ["Your employer matches 401(k) savings up to 4% of pay. What should you do first?","Save at least 4% to get the full match",["Save at least 4% to get the full match","Save nothing until you're older","Save 1%","Take the match in cash"]],
  ["You have a card balance at 24% APR and savings earning 4%. Which plan usually saves the most money?","Pay down the card first, while keeping a small emergency fund",["Pay down the card first, while keeping a small emergency fund","Keep the card balance and save more","Pay only the minimum","Open a second card"]]][k];
  return{q:Q[0],choices:shuffle(rng,Q[2]),correctText:Q[1],hint:`Use the guidelines from weeks 5 through 8.`,steps:[`${Q[1]}.`]}}
});

/* ================= Week 6 ================= */
const W6 = {title:"Credit cards", sub:"Borrowing with plastic: limits, interest and the minimum‑payment trap", days:[
 {title:"How credit cards work", desc:"Limits, statements, grace periods and APR", steps:[
  {h:"Borrowing, not spending", t:`<p>A <b>debit card</b> spends money you already have. A <b>credit card</b> borrows money from a bank, and you pay it back later.</p><p>Every card has a <b>credit limit</b>, the most you can borrow. Whatever you haven't used is your <b>available credit</b>.</p><div class="formula">Available credit = credit limit − balance</div>`,
   b:()=>work("A $2,000 limit",["Balance: $640","Available: $2,000 − $640 = $1,360","He buys a $200 jacket","Available now: $1,160"],"$1,160 of available credit left")},
  {h:"The monthly cycle", t:`<p>Each month is a <b>billing cycle</b>. At the end, the bank sends a <b>statement</b> listing every purchase and the <b>statement balance</b>.</p><p>You then have a <b>grace period</b>, usually at least three weeks, until the due date. Pay the full statement balance by then and you pay <b>no interest</b> on purchases.</p>`,
   b:()=>work("Two ways to handle a $500 statement",["Pay $500 by the due date: $0 interest","Pay $100: interest is charged on the other $400","The second choice also loses the grace period on new purchases until the balance is paid off"],"Pay in full and the card is free to use")},
  {h:"APR and the monthly rate", t:`<p>Card interest is quoted as an <b>APR</b>, often 20% or more. Banks charge it monthly, so they use the <b>monthly periodic rate</b>.</p><div class="formula">Monthly rate = APR ÷ 12</div><p>On a $1,000 balance at 24%, that's 2% a month: $20 of interest in a single month.</p>`,
   b:()=>`<div class="board"><h4>Interest on a $1,000 balance for one month</h4><table><tr><th>APR</th><th>Monthly rate</th><th>Interest</th></tr>${[15.99,19.99,24.99,29.99].map(a=>`<tr><td>${a}%</td><td>${nf(a/12,3)}%</td><td>${$m(r2(1000*a/1200))}</td></tr>`).join("")}</table></div>`},
  {h:"Utilization", t:`<p><b>Credit utilization</b> is the share of your limit you're using. Lenders watch it closely, and it's a big part of your credit score, which you'll study in week 8.</p><div class="formula">Utilization = balance ÷ credit limit</div><p>A common guideline is to stay under 30%, and lower is better.</p>`,
   b:()=>work("$900 balance, $3,000 limit",["900 ÷ 3,000 = 0.30","Utilization: 30%","Paying down to $300 drops it to 10%"])}
 ], practice:["cc_avail","cc_terms_mc","cc_mpr","cc_util","cc_month_int","cc_terms_mc","cc_avail","cc_util","cc_month_int","cc_mpr"]},
 {title:"How card interest is figured", desc:"Average daily balance and the yearly cost", steps:[
  {h:"Balances change every day", t:`<p>Your card balance moves all month: purchases push it up, payments pull it down. So most banks don't charge interest on a single balance. They use the <b>average daily balance</b>.</p><div class="formula">Average daily balance = (sum of each day's balance) ÷ days in the cycle</div>`,
   b:()=>work("A 30‑day cycle",["$400 for 10 days: 400 × 10 = 4,000","$700 for 20 days: 700 × 20 = 14,000","Sum: 18,000","Average: 18,000 ÷ 30 = $600"],"Average daily balance: $600")},
  {h:"The daily rate", t:`<p>The bank turns the APR into a <b>daily rate</b>, then charges it for every day in the cycle.</p><div class="formula">Interest = average daily balance × (APR ÷ 365) × days</div><p>The answer is close to the simpler balance × APR ÷ 12, but not exactly the same.</p>`,
   b:()=>work("$600 average, 21.99% APR, 30 days",["Daily rate: 0.2199 ÷ 365 = 0.00060247","600 × 0.00060247 × 30 = $10.84"],"Interest this cycle: $10.84")},
  {h:"The yearly cost", t:`<p>Carrying a balance month after month adds up fast. For a rough yearly cost, multiply the balance by the APR.</p><p>A $3,000 balance at 24% costs about $720 a year, money that buys nothing at all.</p>`,
   b:()=>{const a=[1000,2000,3000,4000,5000];return `<div class="board"><h4>Yearly interest at 24% APR</h4>${barChart(a.map(x=>x*.24),a.map(x=>"$"+x/1000+"k"),v=>"$"+Math.round(v))}<div class="cap">Bars show the interest, not the balance.</div></div>`}}
 ], practice:["cc_adb","cc_adb_int","cc_year","cc_month_int","cc_adb","cc_adb_int","cc_year","cc_adb","cc_adb_int","cc_util"]},
 {title:"The minimum‑payment trap", desc:"Minimum payments, payoff time and fees", steps:[
  {h:"The minimum payment", t:`<p>Every statement shows a <b>minimum payment</b>, often the greater of a small percent of the balance or a fixed amount like $25.</p><p>Paying the minimum keeps the account in good standing. It doesn't get you out of debt quickly, because most of it goes to interest.</p>`,
   b:()=>work("$3,000 at 24%, minimum $60",["Interest this month: 3,000 × 0.02 = $60","Payment: $60","Toward the balance: $60 − $60 = $0"],"He paid $60 and still owes $3,000")},
  {h:"How long to pay it off", t:`<p>If he stops using the card and pays the same amount each month, this formula gives the number of months:</p><div class="formula">n = −log(1 − r × B ÷ P) ÷ log(1 + r)</div><p>B is the balance, P the monthly payment, and r the monthly rate as a decimal. Round up, since the last month still needs a payment.</p>`,
   b:()=>{const r=.24/12,n1=payoffN(3000,24,75),n2=payoffN(3000,24,150);return work("$3,000 at 24% (r = 0.02)",[`Paying $75: n = −log(1 − 0.8) ÷ log(1.02) = ${nf(n1,1)} → ${Math.ceil(n1)} months`,`Paying $150: n = −log(1 − 0.4) ÷ log(1.02) = ${nf(n2,1)} → ${Math.ceil(n2)} months`],"Doubling the payment cuts the time by more than half")}},
  {h:"Watching the balance fall", t:`<p>The chart shows the same $3,000 balance paid off at $75 a month and at $150 a month.</p><p>At $75, the balance barely moves for the first year. At $150 it falls steadily, and the total interest is far smaller.</p>`,
   b:()=>{const run=p=>{let b=3000,o=[];for(let m=0;m<=84;m++){o.push(Math.max(b,0));b=b*1.02-p}return o};const xs=[...Array(85).keys()];return `<div class="board"><h4>$3,000 at 24%</h4>${lineChart([{vals:run(75),label:"$75/mo",color:"var(--bad)"},{vals:run(150),label:"$150/mo",color:"var(--note)"}],xs.map(m=>m%12===0?String(m/12)+"y":""),kFmt)}<div class="cap">Years along the bottom. At $75 a month it takes about 7 years.</div></div>`}},
  {h:"Fees to watch", t:`<p><b>Late fee:</b> charged when you miss the due date. <b>Cash advance:</b> using the card for cash, with a fee and a higher APR that starts right away. <b>Balance transfer:</b> moving a balance to a new card, usually for a fee of 3% to 5%.</p><p>A 0% intro rate can help, but only if the balance is gone before the intro period ends.</p>`,
   b:()=>work("A $4,000 balance transfer",["Fee: 4,000 × 0.03 = $120","0% for 15 months","To clear it in time: 4,120 ÷ 15 = $274.67 a month"])}
 ], practice:["cc_minpay","cc_split","cc_payoff","cc_fee","cc_total_int","cc_minpay","cc_split","cc_payoff","cc_fee","cc_total_int"]},
 {quiz:true, title:"Week 6 quiz", desc:`10 questions, ${PASS_MARK}% opens week 7`, steps:[
  {h:"Before the quiz", t:`<p>10 questions from this week. No hints, one try each. You need ${PASS_MARK}% to open week 7.</p>`,
   b:()=>`<div class="board"><h4>From this week</h4><table><tr><td>Available credit</td><td>limit − balance</td></tr><tr><td>Utilization</td><td>balance ÷ limit</td></tr><tr><td>Monthly rate</td><td>APR ÷ 12</td></tr><tr><td>Cycle interest</td><td>ADB × APR ÷ 365 × days</td></tr><tr><td>Payoff months</td><td>−log(1 − rB ÷ P) ÷ log(1 + r)</td></tr></table></div>`}
 ], quizFrom:["cc_util","cc_avail","cc_mpr","cc_month_int","cc_terms_mc","cc_adb","cc_adb_int","cc_minpay","cc_split","cc_fee","cc_total_int"]}
]};

/* ================= Week 7 ================= */
const W7 = {title:"Loans and amortization", sub:"Car loans, payment formulas and where every dollar goes", days:[
 {title:"The payment formula", desc:"Principal, rate, term and the monthly payment", steps:[
  {h:"Parts of a loan", t:`<p>Every loan has a <b>principal</b> (the amount borrowed), an <b>interest rate</b>, and a <b>term</b> (how long you have to repay).</p><p>A <b>secured</b> loan has <b>collateral</b> the lender can take if you stop paying: the car on a car loan, the house on a mortgage. Most credit cards are <b>unsecured</b>, which is one reason their rates are higher.</p>`,
   b:()=>work("A car loan",["Principal: $18,000","APR: 6%","Term: 5 years = 60 monthly payments","Collateral: the car"])},
  {h:"Equal payments", t:`<p>Car loans and mortgages are usually <b>amortized</b>: you make the same payment every month, and by the last one, the loan is gone. The payment comes from this formula:</p><div class="formula">PMT = P × r ÷ (1 − (1 + r)<sup>−n</sup>)</div><p>P is the principal, r the monthly rate (APR ÷ 12, as a decimal), and n the number of months.</p>`,
   b:()=>{const p=loanPay(18000,6,60);return work("$18,000 at 6% for 5 years",["r = 0.06 ÷ 12 = 0.005, n = 60",`(1.005)<sup>−60</sup> = ${nf(Math.pow(1.005,-60),6)}`,`1 − that = ${nf(1-Math.pow(1.005,-60),6)}`,`PMT = 18,000 × 0.005 ÷ ${nf(1-Math.pow(1.005,-60),6)} = ${$m(r2(p))}`],`Monthly payment: ${$m(r2(p))}`)}},
  {h:"The true cost", t:`<p>Multiply the payment by the number of payments to see everything you'll pay. Subtract the principal to see the interest.</p><div class="formula">Total interest = PMT × n − P</div>`,
   b:()=>{const p=r2(loanPay(18000,6,60));return work("The $18,000 loan",[`Total paid: ${$m(p)} × 60 = ${$m(r2(p*60))}`,`Interest: ${$m(r2(p*60))} − $18,000 = ${$m(r2(p*60-18000))}`],"The car really cost about $2,880 more")}}
 ], practice:["ln_terms_mc","ln_pmt","ln_total","ln_pmt","ln_terms_mc","ln_total","ln_pmt","ln_total","ln_terms_mc","ln_pmt"]},
 {title:"Amortization schedules", desc:"Interest, principal and balance, one month at a time", steps:[
  {h:"One row at a time", t:`<p>An <b>amortization schedule</b> shows each payment split into interest and principal. Every row follows the same three steps:</p><div class="formula">Interest = balance × r<br>Principal = payment − interest<br>New balance = balance − principal</div>`,
   b:()=>{let b=18000,p=r2(loanPay(18000,6,60)),rows="";for(let m=1;m<=4;m++){const i=r2(b*.005),pr=r2(p-i);b=r2(b-pr);rows+=`<tr><td>${m}</td><td>${$m(i)}</td><td>${$m(pr)}</td><td>${$m(b)}</td></tr>`}return `<div class="board"><h4>$18,000 at 6%, ${$m(p)} a month</h4><table><tr><th>Month</th><th>Interest</th><th>Principal</th><th>Balance</th></tr>${rows}</table></div>`}},
  {h:"The split shifts", t:`<p>Interest is figured on what you still owe. Early on, you owe the most, so interest takes a big bite. As the balance falls, interest shrinks and more of each payment goes to principal.</p><p>The payment never changes. Only the split does.</p>`,
   b:()=>{const p=r2(loanPay(18000,6,60));let b=18000,I=[],Pp=[];for(let m=1;m<=60;m++){const i=b*.005;I.push(i);Pp.push(p-i);b-=p-i}const xs=[...Array(60).keys()];return `<div class="board"><h4>Each payment, split</h4>${lineChart([{vals:Pp,label:"Principal",color:"var(--note)"},{vals:I,label:"Interest",color:"var(--bad)"}],xs.map(m=>(m+1)%12===0?String((m+1)/12)+"y":""),v=>"$"+Math.round(v))}</div>`}},
  {h:"Longer loans, mortgages", t:`<p>The longer the loan, the more lopsided the early payments. On a 30‑year mortgage, most of the first years' payments go to interest.</p><p>That's why paying extra early has so much power: every extra dollar of principal stops earning interest for the lender for the rest of the loan.</p>`,
   b:()=>{const p=loanPay(300000,6.5,360),i=300000*6.5/1200;return work("$300,000 mortgage at 6.5%, 30 years",[`Payment: ${$m(r2(p))}`,`First month's interest: ${$m(r2(i))}`,`First month's principal: ${$m(r2(p-i))}`],`${Math.round(i/p*100)}% of the first payment is interest`)}}
 ], practice:["am_int1","am_prin1","am_trend_mc","am_bal2","am_int1","am_prin1","am_bal2","am_trend_mc","am_prin1","am_bal2"]},
 {title:"Choosing a loan", desc:"Term length, down payments, budgets and extra payments", steps:[
  {h:"Shorter or longer?", t:`<p>A longer term means a smaller monthly payment, which is why sellers push it. But you pay interest for more months, so the total cost goes up.</p>`,
   b:()=>`<div class="board"><h4>$20,000 at 7%</h4><table><tr><th>Term</th><th>Payment</th><th>Total interest</th></tr>${[3,4,5,6,7].map(y=>{const p=r2(loanPay(20000,7,y*12));return `<tr><td>${y} years</td><td>${$m(p)}</td><td>${$m(Math.round(p*y*12-20000))}</td></tr>`}).join("")}</table></div>`},
  {h:"Down payments", t:`<p>A <b>down payment</b> is cash paid up front. It shrinks the loan, which shrinks both the payment and the interest.</p><p>It also protects you: cars lose value fast, and a bigger down payment makes it less likely you'll owe more than the car is worth.</p>`,
   b:()=>{const p=loanPay(16000,7,48);return work("$20,000 car, 20% down, 7% for 4 years",["Down: $4,000","Loan: $16,000",`Payment: ${$m(r2(p))}`])}},
  {h:"Shopping by payment", t:`<p>Start with the payment your budget allows, then work backward to the most you can borrow:</p><div class="formula">P = PMT × (1 − (1 + r)<sup>−n</sup>) ÷ r</div><p>Add your down payment, and you know your price range before you visit a seller.</p>`,
   b:()=>{const r=.07/12,P=350*(1-Math.pow(1+r,-48))/r;return work("$350 a month at 7% for 4 years",[`r = ${nf(r,6)}, n = 48`,`P = 350 × ${nf(1-Math.pow(1+r,-48),6)} ÷ ${nf(r,6)} = ${$m(r2(P))}`],`Borrow up to about ${$m(Math.round(P))}`)}},
  {h:"Paying extra", t:`<p>Most loans let you pay extra, and every extra dollar goes straight to principal. That shortens the loan. To find the new length, use the payoff formula from week 6 with the bigger payment.</p>`,
   b:()=>{const p=r2(loanPay(18000,6,60)),n=payoffN(18000,6,p+50);return work("The $18,000 loan, plus $50 a month",[`New payment: ${$m(r2(p+50))}`,`n = ${nf(n,1)} → ${Math.ceil(n)} months`],`Paid off ${60-Math.ceil(n)} months early`)}}
 ], practice:["ln_compare","ln_down","ln_afford","ln_extra","ln_compare","ln_down","ln_afford","ln_extra","ln_down","ln_afford"]},
 {quiz:true, title:"Week 7 quiz", desc:`10 questions, ${PASS_MARK}% opens week 8`, steps:[
  {h:"Before the quiz", t:`<p>10 questions from this week. No hints, one try each. You need ${PASS_MARK}% to open week 8.</p>`,
   b:()=>`<div class="board"><h4>From this week</h4><table><tr><td>Payment</td><td>P × r ÷ (1 − (1 + r)<sup>−n</sup>)</td></tr><tr><td>Total interest</td><td>PMT × n − P</td></tr><tr><td>Each month</td><td>interest = balance × r</td></tr><tr><td>Max loan</td><td>PMT × (1 − (1 + r)<sup>−n</sup>) ÷ r</td></tr></table></div>`}
 ], quizFrom:["ln_pmt","ln_total","ln_terms_mc","am_int1","am_prin1","am_bal2","am_trend_mc","ln_compare","ln_down","ln_afford","ln_pmt"]}
]};

/* ================= Week 8 ================= */
const W8 = {title:"Credit scores and the cost of borrowing", sub:"How lenders judge you, what it costs, and the loans to avoid", days:[
 {title:"Credit reports and scores", desc:"The bureaus, the report and the five factors", steps:[
  {h:"Your financial report card", t:`<p>Every time you borrow, the lender reports how you pay to <b>credit bureaus</b>. The three national ones are <b>Equifax</b>, <b>Experian</b> and <b>TransUnion</b>.</p><p>Your <b>credit report</b> is the record they keep. A <b>credit score</b> is a single number calculated from it. The most widely used is the FICO score, from 300 to 850.</p>`,
   b:()=>`<div class="board"><h4>FICO score ranges (approximate)</h4><table><tr><td>800–850</td><td>Exceptional</td></tr><tr><td>740–799</td><td>Very good</td></tr><tr><td>670–739</td><td>Good</td></tr><tr><td>580–669</td><td>Fair</td></tr><tr><td>300–579</td><td>Poor</td></tr></table></div>`},
  {h:"The five factors", t:`<p>FICO publishes roughly how much each part of your report counts:</p><ul><li><b>Payment history</b> (35%): do you pay on time?</li><li><b>Amounts owed</b> (30%): including utilization</li><li><b>Length of history</b> (15%)</li><li><b>New credit</b> (10%): recent applications</li><li><b>Credit mix</b> (10%): kinds of credit</li></ul>`,
   b:()=>`<div class="board"><h4>What makes up a FICO score</h4>${barChart([35,30,15,10,10],["Payment","Owed","Length","New","Mix"],v=>Math.round(v)+"%")}</div>`},
  {h:"Utilization across cards", t:`<p>Scores look at utilization on each card and across all of them together. For the overall figure, add every balance and every limit.</p><div class="formula">Overall utilization = total balances ÷ total limits</div>`,
   b:()=>work("Two cards",["Card A: $400 of $2,000","Card B: $1,100 of $3,000","Total: $1,500 ÷ $5,000 = 30%"])},
  {h:"Checking and fixing", t:`<p>You can get free credit reports from all three bureaus at <b>AnnualCreditReport.com</b>. Checking your own report or score is a <b>soft inquiry</b> and doesn't hurt your score. Applying for credit causes a <b>hard inquiry</b>, which can lower it a little.</p><p>Find an error? You have the right to <b>dispute</b> it, and the bureau must investigate.</p>`,
   b:()=>work("Building credit from nothing",["Start with one card, used lightly","Pay the full balance every month","Keep utilization low","Keep the account open for years"])}
 ], practice:["fico_weight","fico_factor","cs_util_total","cs_facts_mc","fico_weight","cs_util_total","fico_factor","cs_facts_mc","cs_util_total","fico_factor"]},
 {title:"What a score is worth", desc:"How your score changes the rate, the payment and the total", steps:[
  {h:"Risk-based pricing", t:`<p>Lenders charge higher rates to borrowers they think are riskier. That's called <b>risk‑based pricing</b>. Your score is the main way they measure risk.</p><p>The same car, the same price, the same loan length, but a different score means a different bill.</p>`,
   b:()=>`<div class="board"><h4>$25,000, 5‑year car loan (sample rates)</h4><table><tr><th>Credit</th><th>APR</th><th>Payment</th><th>Total interest</th></tr>${[["Excellent",5.5],["Good",7.5],["Fair",11.5],["Poor",16]].map(([c,a])=>{const p=r2(loanPay(25000,a,60));return `<tr><td>${c}</td><td>${a}%</td><td>${$m(p)}</td><td>${$m(Math.round(p*60-25000))}</td></tr>`}).join("")}</table></div>`},
  {h:"Comparing two borrowers", t:`<p>To see what a lower score costs, find the payment at each rate. Because both borrow the same amount, the extra interest is just the extra payment times the number of months.</p><div class="formula">Extra interest = (higher PMT − lower PMT) × n</div>`,
   b:()=>{const a=r2(loanPay(25000,5.5,60)),b=r2(loanPay(25000,11.5,60));return work("5.5% vs. 11.5% on $25,000",[`${$m(b)} − ${$m(a)} = ${$m(r2(b-a))} a month`,`× 60 = ${$m(r2((b-a)*60))}`],"A fair score costs over $4,000 more")}},
  {h:"Fees count too", t:`<p>Some loans charge an <b>origination fee</b>, a percent taken out before you get the money. On a $10,000 loan with a 3% fee, you receive $9,700 but repay $10,000 plus interest.</p><p>The APR is supposed to include required fees, which is why comparing APRs works better than comparing interest rates.</p>`,
   b:()=>work("$10,000 personal loan, 3% fee",["Fee: $300","Cash received: $9,700","You still repay all $10,000, plus interest"])}
 ], practice:["rate_diff_pmt","rate_diff_total","fee_pct","rate_diff_pmt","rate_diff_total","fee_pct","rate_diff_total","rate_diff_pmt","fee_pct","rate_diff_total"]},
 {title:"Borrowing traps", desc:"Payday loans, rent‑to‑own and buy now, pay later", steps:[
  {h:"Payday loans", t:`<p>A <b>payday loan</b> is a small, short loan due on your next payday. The cost is quoted as a fee, like $15 per $100 for two weeks. That sounds small, but as an APR it's enormous.</p><div class="formula">APR = two‑week rate × 26</div>`,
   b:()=>work("$15 per $100 for two weeks",["Two‑week rate: 15%","× 26 periods = 390% APR","Compare: a credit card at 24%"],"About 16 times the card's rate")},
  {h:"Rolling over", t:`<p>Many borrowers can't repay in two weeks, so they pay just the fee to <b>roll over</b> the loan. Each rollover costs another fee, and the debt doesn't shrink at all.</p>`,
   b:()=>{const xs=[0,1,2,3,4,5,6,7,8];return `<div class="board"><h4>$400 at $15 per $100, rolled over</h4>${barChart(xs.map(k=>60*(k+1)),xs.map(k=>String(k)),v=>"$"+Math.round(v))}<div class="cap">Total fees by number of rollovers. After 8 rollovers, $540 in fees, and he still owes $400.</div></div>`}},
  {h:"Rent-to-own and pay later", t:`<p><b>Rent‑to‑own</b> stores let you take home a TV or couch for a weekly payment. Add up the payments and the total is often double the store price or more.</p><p><b>Buy now, pay later</b> splits a purchase into a few payments. Some charge no interest, but late fees and the ease of buying more can add up.</p>`,
   b:()=>work("A $600 TV",["Rent‑to‑own: $25 a week for 52 weeks","Total: $1,300","Extra: $700, more than the TV itself"])},
  {h:"The real alternative", t:`<p>Every trap in this lesson is aimed at people with no savings and no other options. The defense is the plan from week 5: an emergency fund, a budget with a surplus, and good credit so better loans are available.</p>`,
   b:()=>work("Cheaper ways to cover a gap",["Emergency fund: free","A loan from family, with a written repayment plan: often free","A small credit union loan: much lower APR","Asking the creditor for a payment plan"])}
 ], practice:["payday_apr","payday_roll","rto_total","trap_mc","payday_apr","rto_total","payday_roll","trap_mc","rto_total","payday_apr"]},
 {quiz:true, title:"Week 8 quiz", desc:`10 questions, ${PASS_MARK}% opens week 9`, steps:[
  {h:"Before the quiz", t:`<p>10 questions from this week. No hints, one try each. You need ${PASS_MARK}% to open week 9.</p>`,
   b:()=>`<div class="board"><h4>From this week</h4><table><tr><td>FICO factors</td><td>35 / 30 / 15 / 10 / 10</td></tr><tr><td>Overall utilization</td><td>total balances ÷ total limits</td></tr><tr><td>Extra interest</td><td>(PMT difference) × n</td></tr><tr><td>Payday APR</td><td>two‑week rate × 26</td></tr></table></div>`}
 ], quizFrom:["fico_weight","fico_factor","cs_util_total","cs_facts_mc","rate_diff_pmt","rate_diff_total","fee_pct","payday_apr","payday_roll","rto_total","trap_mc"]}
]};

/* ================= Week 9: Project ================= */
const W9 = {title:"Project: a first‑year budget", sub:"Your first job, your first apartment, your first full plan", days:[
 {title:"From salary to paycheck", desc:"Turning a job offer into real monthly money", steps:[
  {h:"The project", t:`<p>This week you'll plan your first year on your own, using everything from weeks 1 to 8. Imagine you've just been offered your first full‑time job.</p><p>The question every offer raises: what will this salary actually let me do? The answer starts with turning a yearly salary into monthly take‑home pay.</p>`,
   b:()=>work("The plan, step by step",["1. Salary → monthly take‑home pay","2. Rent, car and bills","3. Savings first, and the emergency fund","4. Stress test: what if something goes wrong?"])},
  {h:"Monthly take-home", t:`<p>Divide the salary by 12, then subtract everything from week 4: pre‑tax 401(k) savings, federal and state income tax on what's left, and FICA on the full gross pay.</p><p>Michigan has a flat state income tax rate, which we'll use as 4.25% in this project.</p>`,
   b:()=>{const g=48000/12,c=g*.05,tx=g-c,f=tx*.1,st=tx*.0425,fi=g*.0765,n=g-c-f-st-fi;return work("$48,000 salary, 5% to a 401(k)",[`Monthly gross: ${$m(g)}`,`401(k): ${$m(c)}; taxable: ${$m(tx)}`,`Federal 10%: ${$m(r2(f))}; state 4.25%: ${$m(r2(st))}`,`FICA: ${$m(r2(fi))}`,`Take‑home: ${$m(r2(n))}`],`About ${$m(Math.round(n))} a month to plan with`)}},
  {h:"The employer match", t:`<p>Many employers <b>match</b> 401(k) savings: put in 4% of your pay and they add another 4%. That's an instant 100% return on those dollars, more than any investment in this course.</p><p>The first rule of a first job: save at least enough to get the full match.</p>`,
   b:()=>work("$48,000 salary, 4% match",["You save 4%: $1,920 a year","Employer adds: $1,920","Total going in: $3,840 a year"],"Skipping the match leaves $1,920 a year on the table")}
 ], practice:["pj_net_month","pay_salary","pretax","pj_net_month","eff_rate","pj_net_month","pay_annual","pj_net_month","pretax","pj_net_month"]},
 {title:"Building the plan", desc:"Rent, a car and every other line of the budget", steps:[
  {h:"How much apartment?", t:`<p>A common guideline is to spend no more than <b>30% of gross pay</b> on rent. Many landlords have a rule of their own and want yearly income of about 40 times the monthly rent.</p><div class="formula">Max rent = monthly gross × 0.30</div>`,
   b:()=>work("$48,000 salary",["Monthly gross: $4,000","30% guideline: $1,200","Landlord's rule: 48,000 ÷ 40 = $1,200"],"Both point to about $1,200")},
  {h:"How much car?", t:`<p>Use the week 7 method: set the payment your budget allows, then work back to the loan. A reliable used car with a solid down payment usually beats a new car with a long loan.</p>`,
   b:()=>{const p=loanPay(12000,7.5,48);return work("$15,000 used car, 20% down",["Loan: $12,000 at 7.5% for 4 years",`Payment: ${$m(r2(p))}`,"Add insurance, gas and repairs to the budget too"])}},
  {h:"Putting it together", t:`<p>Now build the full month: savings first, then the bills, then wants. If the result is negative, something has to change before you sign the lease.</p>`,
   b:()=>{const n=2950;const rows=[["Take‑home pay",n],["Savings, paid first (10%)",-295],["Rent",-1050],["Car payment",-290],["Car insurance",-130],["Food",-420],["Phone",-50],["Utilities",-110]];const left=rows.reduce((a,b)=>a+b[1],0);return `<div class="board"><h4>A first‑year month</h4><table>${rows.map(r=>`<tr><td>${r[0]}</td><td>${$m(r[1])}</td></tr>`).join("")}<tr><td><b>Left for wants and extra savings</b></td><td><b>${$m(left)}</b></td></tr></table></div>`}}
 ], practice:["pj_max_rent","ln_down","pj_left","r503020","pj_max_rent","pj_left","ln_afford","pj_left","pj_max_rent","pj_left"]},
 {title:"The stress test", desc:"Emergencies, debt, savings and raises", steps:[
  {h:"What could go wrong?", t:`<p>Good plans are tested against bad months. What happens if the car needs a $1,200 repair? If you lose your job for two months?</p><p>The emergency fund from week 5 is the answer. Build it first, before investing, so a surprise never turns into credit card debt.</p>`,
   b:()=>work("Essentials: $2,400 a month",["3‑month fund: $7,200","Saving $400 a month: 18 months to build","Until then: no new debt, keep the card paid in full"])},
  {h:"A year of saving", t:`<p>Saving the same amount every month into an account with monthly compounding grows by the regular‑deposit formula, using the monthly rate:</p><div class="formula">FV = D × ((1 + r)<sup>12</sup> − 1) ÷ r</div><p>D is the monthly deposit and r is APR ÷ 12 as a decimal.</p>`,
   b:()=>{const r=.04/12,fv=400*(Math.pow(1+r,12)-1)/r;return work("$400 a month at 4%",[`r = ${nf(r,6)}`,`FV = 400 × (${nf(Math.pow(1+r,12),6)} − 1) ÷ ${nf(r,6)} = ${$m(r2(fv))}`],`${$m(r2(fv-4800))} of interest in year one`)}},
  {h:"When the raise comes", t:`<p>Your first raise is a test. Lifestyle creep says spend it. The plan says send part or all of it to savings before you get used to it.</p><p>Do that with every raise, and your savings rate climbs every year without your budget ever feeling tighter.</p>`,
   b:()=>work("$48,000, 4% raise",["Raise: $1,920 a year","Half to savings: $960 a year","= $80 more saved every month"])}
 ], practice:["ef_target","pj_save_year","pj_raise","pj_check_mc","cc_payoff","pj_save_year","ef_months","pj_raise","pj_check_mc","pj_save_year"]},
 {quiz:true, title:"Week 9 quiz", desc:`10 questions on unit 2, ${PASS_MARK}% opens week 10`, steps:[
  {h:"Before the quiz", t:`<p>This quiz covers your whole first‑year plan, with questions from weeks 4 through 9. No hints, one try each. You need ${PASS_MARK}% to open week 10 and finish unit 2.</p>`,
   b:()=>`<div class="board"><h4>Your plan in one table</h4><table><tr><td>Take‑home</td><td>gross − 401(k) − taxes − FICA</td></tr><tr><td>Max rent</td><td>30% of monthly gross</td></tr><tr><td>Car</td><td>payment formula, down payment</td></tr><tr><td>Emergency fund</td><td>3 to 6 months of essentials</td></tr><tr><td>Savings</td><td>regular‑deposit formula</td></tr></table></div>`}
 ], quizFrom:["pj_net_month","pj_max_rent","pj_left","pj_save_year","pj_raise","pj_check_mc","ln_down","ef_target","cc_total_int","rate_diff_total","r503020"]}
]};
addWeek(6,W6); addWeek(7,W7); addWeek(8,W8); addWeek(9,W9);

Object.assign(DIVES, {
"6-1": {title:"A card in every wallet", sections:[
  ["The forgotten wallet","According to the company's own story, businessman Frank McNamara found himself at a New York restaurant in 1949 without his wallet. The next year he and a partner launched Diners Club, a card that let members eat at participating restaurants and pay one bill at the end of the month. It's usually called the first modern general‑purpose charge card."],
  ["The Fresno drop","In 1958, Bank of America mailed about 60,000 credit cards, unrequested, to almost every household in Fresno, California. Unlike Diners Club, these BankAmericards let people carry a balance and pay interest. The program spread nationwide and, in 1976, was renamed Visa."],
  ["Charge card or credit card","A charge card must be paid in full each month. A credit card lets you carry a balance from month to month, for a price. That one difference turned cards from a convenience into one of the biggest sources of consumer debt in the country."]],
 qs:[{q:"Which card is usually called the first modern general‑purpose charge card?",choices:["Diners Club","Visa","American Express Gold","Discover"],why:"Diners Club launched in 1950."},
     {q:"What did Bank of America do in Fresno in 1958?",choices:["Mailed about 60,000 credit cards to households that hadn't asked for them","Opened the first ATM","Closed every branch","Printed the first paper money"],why:"The mass mailing launched BankAmericard."},
     {q:"BankAmericard was later renamed:",choices:["Visa","Mastercard","Diners Club","PayPal"],why:"It became Visa in 1976."}]},
"6-2": {title:"How card companies make money", sections:[
  ["The swipe fee","Every time you pay with a card, the store pays a fee, usually a small percent of the purchase, called an interchange or swipe fee. Most of it goes to the bank that issued your card. Stores build that cost into their prices, so everyone pays it, even people paying cash."],
  ["Interest and fees","The other big sources of profit are interest on balances and fees: late fees, annual fees and cash advance fees. Cardholders who pay in full every month are, for the bank, the least profitable customers."],
  ["Who pays for rewards?","Cash back and points feel free, but they're funded by swipe fees and by the interest that other cardholders pay. A reward card works in your favor only if you pay in full. One month of interest can wipe out a year of rewards."]],
 qs:[{q:"Who pays the interchange fee on a card purchase?",choices:["The store","The cardholder, directly","The government","Nobody"],why:"The merchant pays it on each card sale."},
     {q:"From the bank's point of view, which cardholders are least profitable?",choices:["Those who pay in full every month","Those who carry a balance","Those who pay late","Those who take cash advances"],why:"They pay no interest and no fees."},
     {q:"When is a rewards card a good deal for the cardholder?",choices:["When the balance is paid in full each month","When he carries a balance","When he pays only the minimum","Always"],why:"Interest quickly outweighs rewards."}]},
"6-3": {title:"The CARD Act", sections:[
  ["A law in 2009","After years of complaints about surprise rate hikes and hidden fees, Congress passed the Credit CARD Act of 2009. It changed what card companies are allowed to do and what they must tell you."],
  ["The minimum‑payment box","Since the law, every statement must show how long it would take to pay off the balance making only minimum payments, and how much it would cost in total. It also shows the payment needed to clear the balance in three years. Read that box: it's the trap from today's lesson, in numbers."],
  ["Young borrowers","The law also made it harder for people under 21 to get a card. They need to show their own income that can repay it, or have a cosigner. Before then, card companies often signed up college students with free gifts on campus."]],
 qs:[{q:"When was the Credit CARD Act passed?",choices:["2009","1958","1970","2020"],why:"It became law in 2009."},
     {q:"What must every statement now show?",choices:["How long it takes to pay off the balance with only minimum payments","The bank's profits","Your credit score","A list of stores that accept the card"],why:"The minimum‑payment warning box."},
     {q:"Under the law, someone under 21 needs:",choices:["Their own income to repay, or a cosigner","Nothing special","A college degree","A mortgage"],why:"The law limits cards for young people without income."}]},
"7-1": {title:"Credit unions", sections:[
  ["Owned by the borrowers","A credit union is a bank owned by its members, the people who save and borrow there. It's run as a nonprofit, so instead of paying profits to outside shareholders, it can offer lower loan rates and higher savings rates."],
  ["Farmers in Germany","In the 1800s, many German farmers and craftsmen couldn't get fair loans. Reformers such as Friedrich Wilhelm Raiffeisen set up cooperatives where members pooled their savings and lent to one another. The idea spread around the world."],
  ["The first in America","The first credit union in the United States, St. Mary's Bank, opened in Manchester, New Hampshire, in 1908. Today millions of Americans belong to credit unions, and they're often one of the cheapest places to get a car loan."]],
 qs:[{q:"Who owns a credit union?",choices:["Its members","The government","Outside shareholders","A credit bureau"],why:"Members who save and borrow there own it."},
     {q:"Why can credit unions often offer lower loan rates?",choices:["They're nonprofits owned by members","They never lend money","They charge higher fees","They are run by payday lenders"],why:"Without outside shareholders, more of the benefit goes to members."},
     {q:"The first U.S. credit union opened in 1908 in:",choices:["Manchester, New Hampshire","Fresno, California","Amsterdam","Atlanta, Georgia"],why:"St. Mary's Bank opened there in 1908."}]},
"7-2": {title:"How the 30‑year mortgage was born", sections:[
  ["Five years and a balloon","Before the 1930s, most American home loans were short, often 5 to 10 years. Borrowers usually paid only interest and then owed the whole principal at the end, a balloon payment. Most people simply took out a new loan to pay off the old one."],
  ["The crash","When the Great Depression hit, banks stopped renewing loans. Homeowners who couldn't pay the balloon lost their homes, and foreclosures soared."],
  ["Amortization for everyone","New government programs in 1933 and 1934, the Home Owners' Loan Corporation and the Federal Housing Administration, spread long‑term, fully amortized loans with fixed payments. Over time the 30‑year fixed mortgage became the standard American home loan, and it still is."]],
 qs:[{q:"Before the 1930s, many home loans ended with:",choices:["A large balloon payment","Zero interest","A gift from the bank","Automatic forgiveness"],why:"Borrowers owed the whole principal at the end."},
     {q:"What made the old system collapse?",choices:["Banks stopped renewing loans during the Depression","Interest rates went to zero","Houses got cheaper to build","Credit cards were invented"],why:"Without renewals, borrowers couldn't pay the balloon."},
     {q:"Which loan became the American standard?",choices:["The 30‑year fixed‑rate mortgage","The 5‑year balloon loan","The payday loan","The cash advance"],why:"Long, amortized loans spread from the 1930s on."}]},
"7-3": {title:"The oldest interest caps", sections:[
  ["Hammurabi's limits","The Code of Hammurabi, from Babylon around 1750 BCE, is one of the oldest surviving sets of laws. Among its rules were maximum interest rates: about 20% a year on loans of silver and about 33⅓% on loans of grain."],
  ["Usury laws","A law that caps interest rates is called a usury law. Through history, many societies have had them, based on the idea that very high rates exploit people who have no other choice."],
  ["Caps today","In the United States, interest limits are mostly set state by state, with many exceptions. That's why payday loan rules differ so much from one state to the next. The debate Hammurabi's scribes settled in clay is still going on."]],
 qs:[{q:"The Code of Hammurabi capped interest on silver loans at about:",choices:["20%","2%","100%","390%"],why:"About 20% a year on silver."},
     {q:"A law that caps interest rates is called:",choices:["A usury law","An amortization law","A credit law","A bankruptcy law"],why:"Usury means charging excessive interest."},
     {q:"In the United States, interest caps are mostly set by:",choices:["Each state","Each bank","The borrower","No one, anywhere"],why:"Limits vary state by state."}]},
"8-1": {title:"Where credit scores came from", sections:[
  ["Judgment calls","For most of history, a loan officer decided who got credit, often based on reputation, appearance or who you knew. Decisions could be slow, inconsistent and unfair."],
  ["Fair and Isaac","In 1956, engineer Bill Fair and mathematician Earl Isaac founded a company to use data and statistics for business decisions. Their company, Fair Isaac, built scoring systems for lenders, and in 1989 introduced the general‑purpose FICO score."],
  ["Numbers instead of hunches","A score uses the same rules for everyone and judges only your credit record, not your name or neighborhood. Its weakness: people with no credit history can't be scored well at all, which is why building credit early matters."]],
 qs:[{q:"Who founded the company behind the FICO score?",choices:["Bill Fair and Earl Isaac","Frank McNamara","Sal Khan","Alexander Hamilton"],why:"Fair Isaac was founded in 1956."},
     {q:"When was the general‑purpose FICO score introduced?",choices:["1989","1956","1776","2009"],why:"It arrived in 1989."},
     {q:"One weakness of scoring mentioned in the reading:",choices:["People with no credit history are hard to score","It uses your name","It changes rules for each person","It can't use computers"],why:"No history means little to score."}]},
"8-2": {title:"The bureaus and your rights", sections:[
  ["Over a century of records","Equifax began in 1899 as the Retail Credit Company in Atlanta. Experian and TransUnion grew out of other credit‑reporting businesses. Together, the three keep files on most adults in America."],
  ["The Fair Credit Reporting Act","In 1970, Congress passed the Fair Credit Reporting Act. It gives you the right to see your report, to dispute errors, and to know when information in your report was used against you, such as when you're denied a loan."],
  ["Check it yourself","AnnualCreditReport.com is the official site for free reports from all three bureaus. Errors happen, like a late payment that wasn't late or an account that isn't yours. Checking regularly is also one of the best ways to spot identity theft."]],
 qs:[{q:"Equifax began in 1899 as:",choices:["The Retail Credit Company","Diners Club","Bank of America","The Federal Reserve"],why:"It started as the Retail Credit Company in Atlanta."},
     {q:"Which law gives you the right to dispute errors on your credit report?",choices:["The Fair Credit Reporting Act","The Credit CARD Act","The Social Security Act","The Fair Labor Standards Act"],why:"The FCRA of 1970."},
     {q:"Besides finding mistakes, checking your report helps you spot:",choices:["Identity theft","Inflation","Higher pay","Tax refunds"],why:"Accounts you didn't open are a warning sign."}]},
"8-3": {title:"Loan sharks and payday lenders", sections:[
  ["Salary lenders","Around 1900, city workers short on cash often turned to 'salary lenders,' who made small loans against the next paycheck at huge rates. Since the loans were often illegal under state usury laws, collection could be harsh. These lenders were among the first to be called loan sharks."],
  ["A legal small loan","Reformers, led by the Russell Sage Foundation, pushed a model law in 1916 that let licensed lenders make small loans at higher but limited rates. The idea was to give workers a legal option so they wouldn't need the sharks."],
  ["The same problem today","Payday loans are the modern version: small, short, and very expensive, typically $10 to $30 for every $100 borrowed. Some states ban them, some cap them, and some allow them. The best protection is still the oldest: savings, a budget, and good credit."]],
 qs:[{q:"Around 1900, lenders who made small loans against a paycheck at huge rates were called:",choices:["Salary lenders","Credit bureaus","Central bankers","Underwriters"],why:"They were also called loan sharks."},
     {q:"What was the goal of the 1916 model small‑loan law?",choices:["To give workers a legal, limited‑rate option","To ban all lending","To create credit cards","To set the minimum wage"],why:"Licensed lenders could offer small loans at capped rates."},
     {q:"Payday loans typically cost:",choices:["$10 to $30 for every $100 borrowed","Nothing","$1 for every $1,000 borrowed","The same as a mortgage"],why:"That fee for two weeks adds up to a huge APR."}]},
"9-1": {title:"Common first‑year mistakes", sections:[
  ["Spending the first paycheck twice","Many new workers plan around gross pay, then discover take‑home pay is far smaller. Others spend as if the first big paycheck repeats every week. A written budget, built on take‑home pay, prevents both."],
  ["Skipping the match","A large share of workers don't save enough to get their employer's full 401(k) match. That's turning down part of their pay. Starting at the very first paycheck makes it painless, because you never get used to having that money."],
  ["Upgrading everything at once","A new job often brings a new apartment, a new car and new furniture, all at once, many of them on credit. Each payment looks small. Together they can lock up a paycheck for years. Upgrading slowly, one thing at a time and paid in cash where possible, keeps the plan flexible."]],
 qs:[{q:"A first budget should be built on:",choices:["Take‑home pay","Gross pay","The credit limit","Next year's raise"],why:"Take‑home pay is what you can actually spend."},
     {q:"Not saving enough to get the full 401(k) match is like:",choices:["Turning down part of your pay","Paying a late fee","Lowering your rent","Earning interest"],why:"The match is extra pay for saving."},
     {q:"What does the reading suggest about upgrades?",choices:["Make them slowly, paying cash where possible","Do them all at once","Put them all on credit","Never upgrade anything"],why:"Many small payments together can lock up a paycheck."}]},
"9-2": {title:"Renting your first apartment", sections:[
  ["The application","Landlords usually check income, credit and references. Many want income of about 40 times the monthly rent. A thin credit history might mean a larger deposit or a cosigner, which is another reason to start building credit early."],
  ["The lease and the deposit","A lease is a contract: usually 12 months of rent, rules about pets and repairs, and penalties for leaving early. A security deposit, often one month's rent, is held against damage and returned when you move out, minus repairs. Photograph the apartment on move‑in day."],
  ["Hidden costs","Rent is only the start. Utilities, internet, renter's insurance, furniture and moving costs all come at once. Renter's insurance is usually cheap and covers your belongings, which the landlord's insurance does not."]],
 qs:[{q:"Many landlords want yearly income of about:",choices:["40 times the monthly rent","2 times the monthly rent","The monthly rent","1,000 times the monthly rent"],why:"A common landlord rule."},
     {q:"Why photograph an apartment on move‑in day?",choices:["To prove its condition when the deposit is returned","For social media","The lease requires a photo","To lower the rent"],why:"It protects your security deposit."},
     {q:"Renter's insurance covers:",choices:["Your belongings","The landlord's building","Your car","Your job"],why:"The landlord's policy doesn't cover tenants' things."}]},
"9-3": {title:"Stress tests", sections:[
  ["Banks under pressure","After the 2008 financial crisis, U.S. regulators began running stress tests on the biggest banks. They imagine a terrible economy, with high unemployment and falling home prices, and check whether each bank would still have enough capital to survive."],
  ["Why test in good times","A stress test is done when things are fine, because that's when there's time to fix the weak spots. After the trouble arrives, it's too late to build a cushion."],
  ["Your own stress test","A household can do the same: what if income stopped for three months? What if a big bill arrived tomorrow? If the answer is 'I'd put it on a card,' the plan needs a bigger emergency fund. That's exactly the test you ran this week."]],
 qs:[{q:"U.S. bank stress tests began after:",choices:["The 2008 financial crisis","World War I","The invention of credit cards","The Great Depression"],why:"Regulators started them after 2008."},
     {q:"Why run a stress test when times are good?",choices:["There's still time to fix weak spots","Banks earn more then","It's required only in good times","Prices are lower"],why:"After trouble starts, it's too late to build a cushion."},
     {q:"If your answer to a surprise bill is 'put it on a card,' the plan needs:",choices:["A bigger emergency fund","A higher credit limit","A payday loan","A longer car loan"],why:"Savings, not debt, should absorb surprises."}]}
});

GLOSSARY.push(
 ["Credit card","A card that borrows money from a bank, to be repaid later.",6],["Credit limit","The most a card lets you borrow.",6],["Available credit","Credit limit minus the current balance.",6],
 ["Billing cycle","The period covered by one card statement, usually about a month.",6],["Statement balance","The amount owed at the end of a billing cycle.",6],
 ["Grace period","Time between the statement and the due date when purchases are interest‑free if the full balance is paid.",6],
 ["Monthly periodic rate","A card's APR divided by 12.",6],["Average daily balance","The average of each day's balance in a billing cycle, used to figure card interest.",6],
 ["Credit utilization","Balance divided by credit limit, as a percent.",6],["Minimum payment","The smallest payment allowed by the due date.",6],
 ["Cash advance","Using a credit card to get cash, usually with a fee and higher interest that starts right away.",6],["Balance transfer","Moving a balance from one card to another, usually for a fee.",6],
 ["Principal","The amount borrowed, not counting interest.",7],["Term","How long a borrower has to repay a loan.",7],["Collateral","Property a lender can take if a secured loan isn't repaid.",7],
 ["Secured loan","A loan backed by collateral.",7],["Unsecured loan","A loan with no collateral.",7],["Cosigner","A person who promises to repay a loan if the borrower doesn't.",7],
 ["Amortization","Paying off a loan with equal payments covering interest and principal.",7],["Amortization schedule","A table showing each payment split into interest and principal.",7],
 ["Down payment","Cash paid up front, reducing the amount borrowed.",7],["Mortgage","A loan to buy a home, secured by the home.",7],["Credit union","A nonprofit bank owned by its members.",7],
 ["Credit bureau","A company that keeps credit records: Equifax, Experian or TransUnion.",8],["Credit report","The record of a person's borrowing and payments.",8],
 ["Credit score","A number, such as a FICO score from 300 to 850, summarizing a credit report.",8],["Hard inquiry","A lender's credit check after you apply for credit.",8],
 ["Soft inquiry","A credit check that doesn't affect your score, such as checking your own.",8],["Risk‑based pricing","Charging riskier borrowers higher interest rates.",8],
 ["Origination fee","A fee for making a loan, often a percent taken out up front.",8],["Payday loan","A small, short loan due on the next payday, with a very high APR.",8],
 ["Rollover","Paying a fee to extend a payday loan without reducing what is owed.",8],["Rent‑to‑own","Paying weekly for an item, usually costing far more than its price.",8],
 ["Usury law","A law that caps interest rates.",8],
 ["Employer match","Money an employer adds to a worker's retirement savings.",9],["Lease","A rental contract between a tenant and a landlord.",9],
 ["Security deposit","Money held by a landlord against damage, returned at move‑out minus repairs.",9],["Renter's insurance","Insurance covering a tenant's belongings.",9],
 ["Stress test","Checking whether a plan or bank survives a bad scenario.",9]
);
